const raw = $input.all().map((i) => i.json);
const rows = raw.map((r) => Array.isArray(r) ? r : Object.keys(r).sort((a, b) => Number(a) - Number(b)).map((k) => r[k]));
const closed = rows.length > 25 ? rows.slice(0, -1) : rows;
const closes = closed.map((c) => Number(c[4])).filter(Number.isFinite);
const highs = closed.map((c) => Number(c[2])).filter(Number.isFinite);
const lows = closed.map((c) => Number(c[3])).filter(Number.isFinite);

function ema(values, period) {
  const k = 2 / (period + 1);
  let val = values[0];
  for (let i = 1; i < values.length; i++) val = values[i] * k + val * (1 - k);
  return val;
}
function rsi14(values) {
  if (values.length < 15) return 50;
  let gains = 0, losses = 0;
  for (let i = 1; i <= 14; i++) {
    const d = values[i] - values[i - 1];
    if (d >= 0) gains += d; else losses += Math.abs(d);
  }
  let avgG = gains / 14, avgL = losses / 14;
  for (let i = 15; i < values.length; i++) {
    const d = values[i] - values[i - 1];
    avgG = (avgG * 13 + (d > 0 ? d : 0)) / 14;
    avgL = (avgL * 13 + (d < 0 ? Math.abs(d) : 0)) / 14;
  }
  if (avgL === 0) return 100;
  return 100 - 100 / (1 + avgG / avgL);
}
function atr14(h, l, c) {
  const trs = [];
  for (let i = 1; i < c.length; i++) {
    trs.push(Math.max(h[i] - l[i], Math.abs(h[i] - c[i - 1]), Math.abs(l[i] - c[i - 1])));
  }
  const slice = trs.slice(-14);
  return slice.reduce((a, b) => a + b, 0) / Math.max(1, slice.length);
}

const price = closes[closes.length - 1] || 0;
const ema20 = ema(closes, 20);
const ema50 = ema(closes, 50);
const rsi = rsi14(closes);
const atr = atr14(highs, lows, closes);
let type = 'HOLD';
if (rsi <= 38 || (price > ema20 && ema20 > ema50 && rsi < 68)) type = 'BUY';
else if (rsi >= 68 || (price < ema20 && ema20 < ema50 && rsi > 32)) type = 'SELL';

const slDist = Math.max(atr * 1.5, price * 0.008);
const tpDist = slDist * 2.4;
const stopLoss = type === 'SELL' ? price + slDist : price - slDist;
const target = type === 'SELL' ? price - tpDist : price + tpDist;
const confidence = type === 'HOLD' ? 58 : Math.min(91, Math.round(68 + Math.abs(50 - rsi) * 0.6));

return [{
  json: {
    kind: 'signal',
    items: [{
      id: 'n8n:BTCUSDT:1H',
      pair: 'BTCUSDT',
      symbol: 'BTC',
      type,
      timeframe: '1H',
      assetClass: 'crypto',
      entry: Number(price.toFixed(2)),
      target: Number(target.toFixed(2)),
      stopLoss: Number(stopLoss.toFixed(2)),
      riskRewardRatio: 2.4,
      confidence,
      rsi: Number(rsi.toFixed(2)),
      atr: Number(atr.toFixed(2)),
      indicator: `Closed 1H · RSI(14)=${rsi.toFixed(1)} · EMA20/50`,
      reasons: [
        `Closed-candle RSI(14): ${rsi.toFixed(1)}`,
        `Trend EMA20 ${ema20 >= ema50 ? '>' : '<'} EMA50`,
        `ATR(14) stop distance $${slDist.toFixed(0)}`
      ],
      source: 'n8n-rsi-generator',
      closedCandleTime: new Date(Number(closed[closed.length - 1]?.[6] || Date.now())).toISOString(),
      generated_at: new Date().toISOString()
    }]
  }
}];
